begin;
create extension if not exists pgcrypto;
create schema if not exists private;
create type public.member_role as enum ('owner','recruiter');
create type public.job_status as enum ('draft','active','archived');
create type public.task_status as enum ('queued','running','succeeded','failed','cancelled');
create type public.analysis_status as enum ('queued','running','ready','failed','cancelled');
create type public.decision_status as enum ('pending','shortlisted','talk_first','rejected');

create table public.workspaces(id uuid primary key default gen_random_uuid(),name text not null,retention_days int not null default 30 check(retention_days between 7 and 90),budget_usd numeric(10,4) not null default 10 check(budget_usd>=0),identity_hidden boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.memberships(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),user_id uuid not null,role public.member_role not null,active boolean not null default true,created_at timestamptz not null default now(),unique(workspace_id,user_id));
create index memberships_user_workspace_idx on public.memberships(user_id,workspace_id);
create table public.jobs(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),title text not null check(length(title) between 2 and 200),status public.job_status not null default 'draft',current_version_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,id));
create table public.documents(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,kind text not null check(kind in ('jd','resume')),candidate_id uuid,object_key text,sha256 text not null,mime text not null,byte_count int not null check(byte_count between 0 and 5242880),parser_version text not null,status text not null,original_segments_json jsonb not null default '[]',redacted_segments_json jsonb not null default '[]',redaction_version text,readability_json jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,id),foreign key(workspace_id) references public.workspaces(id));
create table public.job_versions(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,job_id uuid not null,jd_document_id uuid,version_no int not null check(version_no>0),requirements_json jsonb not null default '[]',state text not null check(state in ('extracting','draft','confirmed','failed')),confirmed_by uuid,confirmed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,id),unique(job_id,version_no),foreign key(workspace_id,job_id) references public.jobs(workspace_id,id),foreign key(workspace_id,jd_document_id) references public.documents(workspace_id,id));
alter table public.jobs add constraint jobs_current_version_fk foreign key(workspace_id,current_version_id) references public.job_versions(workspace_id,id) deferrable initially deferred;
create table public.candidates(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,job_id uuid not null,display_name text,candidate_code text not null,decision_status public.decision_status not null default 'pending',decision_version int not null default 0,expires_at timestamptz not null,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,id),unique(workspace_id,candidate_code),foreign key(workspace_id,job_id) references public.jobs(workspace_id,id));
alter table public.documents add constraint documents_candidate_fk foreign key(workspace_id,candidate_id) references public.candidates(workspace_id,id);
create index candidates_workspace_job_created_idx on public.candidates(workspace_id,job_id,created_at desc);
create table public.document_redactions(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,document_id uuid not null,version text not null,segments_json jsonb not null,span_mapping_json jsonb not null,reviewer_id uuid not null,reviewed_at timestamptz not null default now(),unique(document_id,version),foreign key(workspace_id,document_id) references public.documents(workspace_id,id));
create table public.analyses(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,candidate_id uuid not null,job_version_id uuid not null,resume_document_id uuid not null,redaction_version text not null,cache_key text not null,status public.analysis_status not null default 'queued',stage text not null default 'Queued',attempt_count int not null default 0,error_code text,evaluation_as_of date not null,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,id),foreign key(workspace_id,candidate_id) references public.candidates(workspace_id,id),foreign key(workspace_id,job_version_id) references public.job_versions(workspace_id,id),foreign key(workspace_id,resume_document_id) references public.documents(workspace_id,id));
create index analyses_workspace_candidate_created_idx on public.analyses(workspace_id,candidate_id,created_at desc);
create unique index analyses_active_cache_idx on public.analyses(workspace_id,cache_key) where status in ('queued','running','ready');
create table public.reports(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,analysis_id uuid not null unique,schema_version text not null,findings_json jsonb not null,scores_json jsonb not null,questions_json jsonb not null,config_json jsonb not null,created_at timestamptz not null default now(),unique(workspace_id,id),foreign key(workspace_id,analysis_id) references public.analyses(workspace_id,id));
create table public.decisions(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,candidate_id uuid not null,analysis_id uuid not null,status public.decision_status not null check(status<>'pending'),note text not null check(length(note) between 5 and 2000),questions_json jsonb not null default '[]',actor_id uuid not null,decision_version int not null check(decision_version>0),created_at timestamptz not null default now(),unique(candidate_id,decision_version),foreign key(workspace_id,candidate_id) references public.candidates(workspace_id,id),foreign key(workspace_id,analysis_id) references public.analyses(workspace_id,id));
create index decisions_workspace_candidate_version_idx on public.decisions(workspace_id,candidate_id,decision_version);
create table private.task_queue(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id),kind text not null check(kind in ('JD_EXTRACT','RESUME_EXTRACT','ANALYZE','DELETE_CANDIDATE')),resource_id uuid not null,payload_version text not null,status public.task_status not null default 'queued',stage text not null default 'Queued',available_at timestamptz not null default now(),attempt_count int not null default 0,lease_token uuid,lease_owner text,lease_expires_at timestamptz,heartbeat_at timestamptz,last_error_code text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index task_queue_claim_idx on private.task_queue(status,available_at);
create table private.budget_buckets(workspace_id uuid not null references public.workspaces(id),month_start date not null,spent_usd numeric(14,8) not null default 0,reserved_usd numeric(14,8) not null default 0,primary key(workspace_id,month_start));
create table private.budget_reservations(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,task_id uuid not null,attempt_no int not null,amount numeric(14,8) not null check(amount>=0),status text not null check(status in ('reserved','settled','unknown','released')),created_at timestamptz not null default now(),unique(task_id,attempt_no),foreign key(task_id) references private.task_queue(id));
create table private.usage_events(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,task_id uuid not null,attempt_no int not null,provider text not null,model text not null,input_tokens int,output_tokens int,other_billed_tokens int,cost_usd numeric(14,8),usage_state text not null,price_snapshot jsonb not null,created_at timestamptz not null default now(),unique(task_id,attempt_no));
create table private.idempotency_keys(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,actor_id uuid not null,route text not null,key text not null,request_hash text not null,response_ref uuid not null,expires_at timestamptz not null,created_at timestamptz not null default now(),unique(actor_id,route,key));
create table private.deletion_ledger(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,opaque_resource_id uuid not null,deleted_at timestamptz not null default now());
create table public.audit_events(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,actor_id uuid,event_type text not null,resource_id uuid,safe_metadata_json jsonb not null default '{}',created_at timestamptz not null default now());

create or replace function private.is_member(ws uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.memberships m where m.workspace_id=ws and m.user_id=auth.uid() and m.active)$$;
create or replace function private.is_owner(ws uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.memberships m where m.workspace_id=ws and m.user_id=auth.uid() and m.active and m.role='owner')$$;
grant execute on function private.is_member(uuid),private.is_owner(uuid) to authenticated;
alter table public.workspaces enable row level security; alter table public.memberships enable row level security; alter table public.jobs enable row level security; alter table public.job_versions enable row level security; alter table public.candidates enable row level security; alter table public.documents enable row level security; alter table public.document_redactions enable row level security; alter table public.analyses enable row level security; alter table public.reports enable row level security; alter table public.decisions enable row level security; alter table public.audit_events enable row level security;
create policy workspaces_read on public.workspaces for select using(private.is_member(id));
create policy memberships_read on public.memberships for select using(private.is_member(workspace_id));
create policy jobs_read on public.jobs for select using(private.is_member(workspace_id));
create policy job_versions_read on public.job_versions for select using(private.is_member(workspace_id));
create policy candidates_read on public.candidates for select using(private.is_member(workspace_id) and deleted_at is null);
create policy documents_read on public.documents for select using(private.is_member(workspace_id) and (not (select identity_hidden from public.workspaces where id=workspace_id) or private.is_owner(workspace_id)));
create policy redactions_read on public.document_redactions for select using(private.is_member(workspace_id));
create policy analyses_read on public.analyses for select using(private.is_member(workspace_id));
create policy reports_read on public.reports for select using(private.is_member(workspace_id));
create policy decisions_read on public.decisions for select using(private.is_member(workspace_id));
create policy audit_owner_read on public.audit_events for select using(private.is_owner(workspace_id));
revoke all on schema private from anon,authenticated;
revoke insert,update,delete on public.reports,public.analyses,public.audit_events from anon,authenticated;

create or replace function private.claim_task(worker text) returns setof private.task_queue language plpgsql security definer set search_path='' as $$declare picked private.task_queue;begin select * into picked from private.task_queue where (status='queued' and available_at<=now()) or (status='running' and lease_expires_at<now()) order by available_at,id for update skip locked limit 1; if picked.id is null then return; end if; update private.task_queue set status='running',lease_token=gen_random_uuid(),lease_owner=worker,lease_expires_at=now()+interval '120 seconds',heartbeat_at=now(),attempt_count=attempt_count+1,updated_at=now() where id=picked.id returning * into picked; return next picked;end$$;
create or replace function private.heartbeat_task(task_id uuid,token uuid) returns boolean language plpgsql security definer set search_path='' as $$begin update private.task_queue set heartbeat_at=now(),lease_expires_at=now()+interval '120 seconds',updated_at=now() where id=task_id and lease_token=token and status='running' and lease_expires_at>=now(); return found;end$$;
create or replace function private.complete_task(task_id uuid,token uuid) returns boolean language plpgsql security definer set search_path='' as $$begin update private.task_queue set status='succeeded',stage='Ready',lease_expires_at=null,updated_at=now() where id=task_id and lease_token=token and status='running' and lease_expires_at>=now(); return found;end$$;
revoke all on function private.claim_task(text),private.heartbeat_task(uuid,uuid),private.complete_task(uuid,uuid) from public,anon,authenticated;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('candidate-documents','candidate-documents',false,5242880,array['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','text/plain']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy storage_member_read on storage.objects for select to authenticated using(bucket_id='candidate-documents' and private.is_member((storage.foldername(name))[1]::uuid) and (not coalesce((select identity_hidden from public.workspaces where id=(storage.foldername(name))[1]::uuid),true) or private.is_owner((storage.foldername(name))[1]::uuid)));
commit;
